    expandingPatternsIntro: 'Im Gegensatz zu klassischen Dreiecken, die sich verengen, EXPANDIEREN diese Muster: Die Trendlinien divergieren und bilden höhere Hochs und tiefere Tiefs. Sie spiegeln Unentschlossenheit und steigende Volatilität wider. Die Strategie nutzt 2 Einstiege (E1 = erster Ausbruch, E2 = bestätigter Retest) mit doppeltem Take Profit (T1 = Musterhöhe, T2 = erweiterte Projektion).',
    expandingPatternsTradePlan: 'Trade-Plan',
    expandingPatternsTarget: 'Ziel (projizierte Höhe)',
    expandingPatternsAscWedgeName: 'Aufsteigender Broadening-Keil',
    expandingPatternsAscWedgeDesc: 'BÄRISCHE UMKEHR im reifen Aufwärtstrend. Beide Linien steigen, divergieren aber und erzeugen wachsende Volatilität. Der Bruch der unteren Linie löst eine starke Korrektur aus. Stop Loss über dem letzten Hoch, Ziel = Keilhöhe nach unten projiziert.',
    expandingPatternsBullContName: 'Bullisches Broadening-Dreieck (Fortsetzung)',
    expandingPatternsBullContDesc: 'BULLISCHE FORTSETZUNG. Der ansteigende Broadening-Keil dient als Akkumulationszone im Aufwärtstrend. Ausbruch nach oben bestätigt die Fortsetzung. T1 = Minimalhöhe, T2 = volle projizierte Höhe.',
    expandingPatternsBearRevName: 'Bärisches Broadening-Dreieck (Bullische Umkehr)',
    expandingPatternsBearRevDesc: 'BULLISCHE UMKEHR am Ende eines Abwärtstrends. Verkaufsdruck lässt nach, Käufer treten an steigenden Tiefs auf. Ausbruch nach oben = neuer Bullenzyklus. Doppelter Einstieg mit Stops unter dem letzten Tief.',
    expandingPatternsBearContName: 'Bärisches Broadening-Dreieck (Fortsetzung)',
    expandingPatternsBearContDesc: 'BÄRISCHE FORTSETZUNG. Volatile Pause in einem klaren Abwärtstrend, bevor der Fall wieder aufgenommen wird. Der Abwärtsausbruch bestätigt die Fortsetzung mit Ziel gleich Musterhöhe.',
    expandingPatternsBearRevDownName: 'Bärisches Broadening-Dreieck (Bärische Umkehr)',
    expandingPatternsBearRevDownDesc: 'BÄRISCHE UMKEHR nach einem Aufwärtstrend. Höhere Hochs werden schwächer, Käufer verlieren die Kontrolle. Bruch der unteren Unterstützung bestätigt den Trendwechsel.',
