    testimonialsSubtitle_l002: 'Hunderte professionelle und private Trader optimieren bereits ihre Strategien mit Trading Calculator PRO.',
    faqTitle_l003: 'Häufig gestellte Fragen',
    faqSubtitle_l004: 'Die häufigsten Fragen vor dem Start.',
    testimonial1Quote_l010: 'Ich bin vom Blindflug zu klaren R/R-, Position-Size- und Win-Rate-Metriken übergegangen. Mein Konto erleidet keine brutalen Drawdowns mehr.',
    testimonial1Author_l011: 'Carlos M.',
    testimonial1Role_l012: 'Krypto Day Trader · 4 Jahre',
    testimonial2Quote_l020: 'Der Strategy Optimizer und der AI Coach sparen mir stundenlange Analysen. Die Kosten rechtfertige ich jeden Monat mit einem einzigen gut geplanten Trade.',
    testimonial2Author_l021: 'Ana R.',
    testimonial2Role_l022: 'Optionen Swing Trader',
    testimonial3Quote_l030: 'Ich nutze es seit 8 Monaten täglich. Monte Carlo und das Journal haben meine Sicht auf Risiko verändert. 5 Sterne.',
    testimonial3Author_l031: 'David L.',
    testimonial3Role_l032: 'Unabhängiger Trader · Forex',
    faqQ1_l040: 'Muss ich Experte sein, um es zu nutzen?',
    faqA1_l041: 'Nein. Die App führt Schritt für Schritt durch jeden Rechner und das Education Center deckt alles ab – von den Grundlagen (was ist ein Stop Loss) bis zu fortgeschrittenen Optionsstrategien. Es gibt einen kostenlosen Demo Trader, um alles risikofrei auszuprobieren.',
    faqQ2_l050: 'Kann ich das Abo jederzeit kündigen?',
    faqA2_l051: 'Ja. Kündige mit 1 Klick in deinem Profil. Keine Vertragsbindung. Bei Lifetime-Kauf ist der Zugang dauerhaft – ohne wiederkehrende Zahlungen.',
    faqQ3_l060: 'Welche Assets werden unterstützt?',
    faqA3_l061: 'Krypto, Forex (28 Paare), US-Aktien (NYSE/NASDAQ), Indizes (SPX, NDX, DAX, etc.), Rohstoffe und Futures. Echtzeitdaten über Yahoo Finance.',
    faqQ4_l070: 'Kostet die KI des Trade Coach extra?',
    faqA4_l071: 'Nein. Der AI Trade Coach (Claude Sonnet 4.5) ist in allen Premium-Plänen enthalten. Er analysiert deine Strategie, identifiziert Risiken und schlägt Verbesserungen wie ein Senior-Mentor vor.',
    faqQ5_l080: 'Funktioniert es auf dem Handy?',
    faqA5_l081: 'Ja. Vollständig responsives Design. Die Rechner und das Dashboard funktionieren perfekt auf iOS/Android. Native App auf der Roadmap für Q2.',
