    trendSubtitle: 'Beherrsche eines der mächtigsten Werkzeuge der technischen Analyse',
    trendBullish: 'Bullische Trendlinie',
    trendBearish: 'Bärische Trendlinie',
    trendBullishDef: 'Bullische Trendlinie',
    trendBullishDefDesc: 'Drawn by connecting two or more higher lows. Acts as dynamic support in an uptrend — price bounces off it as it rises.',
    trendBearishDef: 'Bärische Trendlinie',
    trendBearishDefDesc: 'Drawn by connecting two or more lower highs. Acts as dynamic resistance in a downtrend — price bounces off it as it falls.',
    trendBullChartTitle: 'Bullish Trend Line — Entry Setup',
    trendBearChartTitle: 'Bearish Trend Line — Entry Setup',
