    trendBullStep1Title: 'Identify the uptrend',
    trendBullStep1Desc: 'Confirm series of higher highs and higher lows on your chart',
    trendBullStep2Title: 'Draw the trend line',
    trendBullStep2Desc: 'Connect at least 2 higher lows — 3+ touches make it stronger',
    trendBullStep3Title: 'Wait for a pullback',
    trendBullStep3Desc: 'Price should pull back toward the trend line — patience is key',
    trendBullStep4Title: 'Enter on bounce confirmation',
    trendBullStep4Desc: 'Look for a bullish candle (pin bar, engulfing) bouncing off the trend line',
    trendBullStep5Title: 'Set SL and TP',
    trendBullStep5Desc: 'Stop loss below the trend line, take profit at the next resistance level',
    trendBearStep1Title: 'Identify the downtrend',
