    sessOverlapHours: '13:00 - 17:00 UTC',
    sessOverlapDesc: 'Höchste Liquidität und Volatilität',
    marketTypesIntro: 'Jeder Markt hat eigene Handelszeiten, Liquidität, Volatilität und Treiber. Zu verstehen, was du handelst – und wie sich jeder Markt verhält – ist dein erster Vorteil: dieselbe Strategie kann in einem Markt gewinnen und in einem anderen scheitern.',
    marketParticipantsIntro: 'Der Preis ist das Ergebnis eines Tauziehens zwischen sehr unterschiedlichen Akteuren, jeder mit eigener Größe, eigenem Horizont und eigener Motivation. Zu wissen, wer den Markt bewegt – und warum – hilft dir, den Orderfluss zu lesen, statt gegen ihn zu kämpfen.',
    sessionsIntro: 'Der Markt handelt rund um die Uhr über drei Regionen, die sich ablösen: Asien-Pazifik, Europa und Amerika. Volatilität, Spreads und die besten Instrumente ändern sich mit der Uhr – und in den Überschneidungen der Sessions passiert das meiste Volumen.',
    mktBondsName: 'Anleihen / Festverzinsliche',
    mktBondsDesc: 'Von Staaten und Unternehmen ausgegebene Schulden. Der weltweit größte Markt; Staatsanleiherenditen (etwa die 10-jährige US-Anleihe) bestimmen den \'risikofreien\' Zins, der alle anderen Anlagen bewertet. Bewegt sich invers zu den Zinsen.',
    mktBondsVolume: '~140 Bio. $ ausstehend',
    mktOptionsName: 'Optionen',
    mktOptionsDesc: 'Verträge, die das Recht – nicht die Pflicht – geben, einen Basiswert vor Verfall zu einem festen Preis zu kaufen (Call) oder zu verkaufen (Put). Zum Absichern, zur Ertragserzielung oder zur Spekulation mit Hebel und definiertem Risiko. Der Preis hängt von Volatilität und Zeit ab.',
    mktOptionsVolume: '~50 Mrd. $/Tag (USA)',
    mktCfdsName: 'CFDs',
    mktCfdsDesc: 'Contracts for Difference: Du handelst die Preisänderung eines Basiswerts, ohne ihn zu besitzen – mit Hebel, long wie short. In Europa beliebt für Indizes, Forex und Rohstoffe – doch der Hebel verstärkt Verluste und Kosten (Spread/Overnight-Finanzierung) summieren sich.',
    mktCfdsVolume: 'Broker-abhängig',
    partBanksName: 'Investment- & Geschäftsbanken',
    partBanksDesc: 'Das Rohrleitungssystem des Marktes: Sie stellen Kurse, führen riesige Kundenorders aus, betreiben Eigenhandelstische und dominieren den Devisenmarkt. Ihr Research und Orderfluss prägen die kurzfristige Richtung.',
    partHedgeFundsName: 'Hedgefonds',
    partHedgeFundsDesc: 'Kaum regulierte Fonds, die mit aggressiven, flexiblen Strategien (Long/Short, Makro, Arbitrage, Quant) absolute Renditen anstreben. Sie können Märkte schnell bewegen und sind oft das \'Smart Money\' auf der Gegenseite von Retail-Trades.',
    partFundsName: 'Pensions- & Investmentfonds',
    partFundsDesc: 'Die größten Pools langfristigen Kapitals. Sie investieren langsam und in großem Umfang für Rente und Ersparnisse; ihre Rebalancing-Flüsse und Indexaufnahmen bewegen ganze Sektoren über Wochen und Monate.',
    partHftName: 'HFT & Algorithmen',
    partHftDesc: 'High-Frequency-Trading-Firmen nutzen ultraschnelle Algorithmen, um in Mikrosekunden zu handeln, stellen einen Großteil der heutigen Liquidität und verdienen winzige Spreads über Millionen von Orders. Sie dominieren das Intraday-Volumen.',
    partBrokersName: 'Broker & Dealer',
    partBrokersDesc: 'Die Vermittler, die dir Marktzugang geben. Einige leiten deine Order an die Börse weiter (ECN/STP); andere nehmen die Gegenseite ein (Market Maker/Dealer). Wie sie Orders routen, beeinflusst deine Ausführung und Kosten.',
    partCorporatesName: 'Unternehmen & Hedger',
    partCorporatesDesc: 'Reale Unternehmen (Fluggesellschaften, Exporteure, Minen), die Futures und Devisen nicht zum Spekulieren, sondern zum Absichern realer Risiken nutzen – Treibstoff, Währungen, Rohstoffe. Ihr stetiger, richtungsloser Fluss ist das Rückgrat der Rohstoff- und Devisenmärkte.',
    sessSydneyName: 'Sydney (Pazifik)',
    sessSydneyHours: '22:00–07:00 UTC',
    sessSydneyDesc: 'Die Session, die die Handelswoche eröffnet. Dünne Liquidität und geringe Volatilität; vor allem AUD-, NZD- und JPY-Paare. Gut für Range-Strategien, riskant für Ausbrüche, da Bewegungen erratisch sein können.',
    sessOverlap2Name: 'Überschneidung Sydney–Tokio',
